const headerBefore = 'uygulama veritabanındaki 227 kitabı ve içerik üretimi için seçilen 73 yeni kitabı';
const headerAfter = 'uygulama veritabanındaki 237 kitabı ve içerik üretimi için seçilen 63 yeni kitabı';
if (catalog.includes(headerBefore)) catalog = catalog.replace(headerBefore, headerAfter);
else console.warn('UYARI: katalog başlık sayaçları bulunamadı, elle güncelleyin.');

for (const item of created) {
  const rowBefore = `| ${item.catalogNo} | *${item.book}* | ${item.author} | Tarih | **YENİ ÖNERİ** | — | 0 |`;
  const rowAfter = `| ${item.catalogNo} | *${item.book}* | ${item.author} | Tarih | **DB'DE KAYITLI / V2** | ${item.listNo} | 1 |`;
  if (catalog.includes(rowBefore)) catalog = catalog.replace(rowBefore, rowAfter);
  else console.warn(`UYARI: katalog satırı bulunamadı: ${item.book}`);
}
writeFileSync(paths.catalog, catalog, 'utf8');

